import{a}from"./api.C1xNrEEc.js";import"./AdminLayout.astro_astro_type_script_index_0_lang.ZsBwA2go.js";import"./Toast.astro_astro_type_script_index_0_lang.DEjscZYH.js";const r=async()=>{if(window.authManager.isLoading){setTimeout(r,100);return}if(!window.authManager.isAuthenticated){window.location.href="/login";return}if(window.authManager.currentUser.role!=="ADMIN"){window.location.href="/dashboard",showWarning("Access denied. Admin only.");return}c()},c=async()=>{try{const e=await a.getCategories();if(e.success&&e.data){const o=document.getElementById("categoryId");e.data.forEach(t=>{const n=document.createElement("option");n.value=t.id,n.textContent=t.name,o.appendChild(n)})}}catch(e){console.error("Failed to load categories:",e)}};document.getElementById("createPostForm").addEventListener("submit",async e=>{e.preventDefault();const o={title:document.getElementById("title").value,content:document.getElementById("content").value,summary:document.getElementById("summary").value,categoryId:document.getElementById("categoryId").value?parseInt(document.getElementById("categoryId").value):null,featuredImage:document.getElementById("featuredImage").value};if(!o.title.trim()){showError("Please enter a title");return}if(!o.content.trim()){showError("Please enter content");return}try{const t=await a.createPost(o);if(t.success){showSuccess("Post created successfully!");const n=document.getElementById("publishImmediately").checked,s=t.data.id;n&&(await a.request(`/posts/${s}/publish`,{method:"PUT"}),showSuccess("Post published!")),setTimeout(()=>{window.location.href="/admin/posts"},1e3)}}catch(t){console.error("Failed to create post:",t),showError(t.message||"Failed to create post")}});document.addEventListener("DOMContentLoaded",r);
